// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;
    function setUp() public { c = new Synth(address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(uint256 initialAllowance, uint256 subtractedValue, address owner, address spender) public {
        vm.assume(owner != address(0));
        vm.assume(spender != address(0));
        vm.assume(owner != spender);
        initialAllowance = bound(initialAllowance, 0, type(uint256).max - uint256(1));
        subtractedValue = bound(subtractedValue, 0, initialAllowance);

        vm.prank(owner);
        c.approve(spender, initialAllowance);
        assertEq(c.allowance(owner, spender), initialAllowance, "setup: allowance mismatch");

        vm.prank(owner);
        bool ok = c.decreaseAllowance(spender, subtractedValue);
        assertTrue(ok, "decreaseAllowance must return true");

        uint256 expected = initialAllowance - subtractedValue;
        uint256 actual = c.allowance(owner, spender);
        assertTrue(actual == expected, "allowance must decrease by subtractedValue exactly");
    }
}

